# Helper: gcd
def gcd(a, b):
    while b:
        a, b = b, a % b
    return abs(a)

# Helper: divisors
def divisors(n):
    ds = []
    for i in range(1, int(math.isqrt(n)) + 1):
        if n % i == 0:
            ds.append(i)
            if i * i != n:
                ds.append(n // i)
    return ds

# Build a pool of small primitive Pythagorean triples (r, q, s) with s hypotenuse
triples = []
for m in range(2, 8):
    for n in range(1, m):
        if ((m - n) % 2 == 1) and gcd(m, n) == 1:
            r = m*m - n*n
            q = 2*m*n
            s = m*m + n*n
            triples.append((r, q, s))
rng.shuffle(triples)

# Try to generate nontrivial instance
for _ in range(500):
    if not triples:
        # Rebuild if exhausted
        for m in range(2, 8):
            for n in range(1, m):
                if ((m - n) % 2 == 1) and gcd(m, n) == 1:
                    r = m*m - n*n
                    q = 2*m*n
                    s = m*m + n*n
                    triples.append((r, q, s))
        rng.shuffle(triples)
    r, q, s = rng.choice(triples)

    # Pick t, v (scale parameters)
    t = rng.randint(2, 8)
    v = rng.randint(2, 8)

    # Choose u as a divisor of s, but try to avoid making CD integral
    divs = divisors(s)
    rng.shuffle(divs)
    # prefer larger u to reduce chance of dividing v^2*r completely
    for u in divs:
        # Construct sides ensuring sqrt(ac) multiple of s and BD integer
        # a = s * u * t^2, c = (s * v^2) // u, requiring u | s*v^2
        if (s * v * v) % u != 0:
            continue
        a = s * u * t * t
        c = (s * v * v) // u
        # BD length (angle bisector) derived to be integer: bd = t * v * q
        bd = t * v * q

        # Triangle inequality for side AC = (a + c) * (r / s)
        # b = (a + c) * r / s must be > |a - c|
        # Work with integers by cross-multiplying
        lhs_num = (a + c) * r  # numerator over s
        rhs = abs(a - c) * s
        if lhs_num <= rhs:
            continue

        # Ensure nontrivial CD: CD = c * r / s has denominator > 1 after reduction
        num_cd = c * r
        den_cd = s
        g = gcd(num_cd, den_cd)
        den_red = den_cd // g
        if den_red <= 1:
            continue

        # Sanity: bd^2 < a*c
        if bd * bd >= a * c:
            continue

        return {'ab': a, 'bc': c, 'bd': bd}

# Fallback (should rarely happen): pick a safe configuration
# Use triple (3,4,5), t=3, v=4, u=5 => a=5*5*9=225, c=(5*16)/5=16, bd=3*4*4=48
return {'ab': 225, 'bc': 16, 'bd': 48}

